// Extension helper for SessionStateTempDataProvider
namespace Microsoft.AspNetCore.Mvc.ViewFeatures
{
    internal static class SessionStateTempDataProviderOptionsExtensions
    {
        public static ITempDataProvider CreateProvider(this SessionStateTempDataProviderOptions options)
        {
            // Return a no-op temp data provider for tests
            return new TestTempDataProvider();
        }
    }

    internal class TestTempDataProvider : ITempDataProvider
    {
        private IDictionary<string, object> _data = new Dictionary<string, object>();

        public IDictionary<string, object> LoadTempData(HttpContext context) => _data;

        public void SaveTempData(HttpContext context, IDictionary<string, object> values)
        {
            _data = values;
        }
    }
}

