using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateWithData(string dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        private static void SeedData(SchoolContext context)
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 100000m,
                StartDate = new DateTime(2020, 1, 1)
            };
            context.Departments.Add(dept);

            var instructor = new Instructor
            {
                ID = 1,
                LastName = "Smith",
                FirstMidName = "John",
                HireDate = new DateTime(2015, 6, 1),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Room 101" }
            };
            context.Instructors.Add(instructor);

            var course1 = new Course
            {
                CourseID = 1001,
                Title = "Intro to CS",
                Credits = 3,
                DepartmentID = 1,
                Department = dept,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            var course2 = new Course
            {
                CourseID = 1002,
                Title = "Data Structures",
                Credits = 4,
                DepartmentID = 1,
                Department = dept,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Courses.AddRange(course1, course2);

            var student1 = new Student
            {
                ID = 1,
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2021, 9, 1),
                Enrollments = new List<Enrollment>()
            };
            var student2 = new Student
            {
                ID = 2,
                LastName = "Adams",
                FirstMidName = "Bob",
                EnrollmentDate = new DateTime(2022, 1, 15),
                Enrollments = new List<Enrollment>()
            };
            context.Students.AddRange(student1, student2);

            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 1001,
                StudentID = 1,
                Grade = Grade.A,
                Course = course1,
                Student = student1
            };
            context.Enrollments.Add(enrollment);
            student1.Enrollments.Add(enrollment);
            course1.Enrollments.Add(enrollment);

            var ca = new CourseAssignment { CourseID = 1001, InstructorID = 1, Course = course1, Instructor = instructor };
            context.CourseAssignments.Add(ca);
            instructor.CourseAssignments.Add(ca);
            course1.CourseAssignments.Add(ca);

            context.SaveChanges();
        }
    }
}

