using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDatabase_SeedsAllData()
        {
            var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
            Assert.Equal(7, context.Courses.Count());
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.True(context.Enrollments.Count() >= 11);
            Assert.True(context.CourseAssignments.Count() >= 8);
        }

        [Fact]
        public void Initialize_DatabaseAlreadySeeded_DoesNotDuplicate()
        {
            var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);
            var studentCount = context.Students.Count();

            // Call again
            DbInitializer.Initialize(context);

            Assert.Equal(studentCount, context.Students.Count());
        }

        [Fact]
        public void Initialize_SetsCorrectDepartmentAdministrators()
        {
            var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var english = context.Departments.First(d => d.Name == "English");
            Assert.NotNull(english.InstructorID);

            var instructor = context.Instructors.Find(english.InstructorID);
            Assert.Equal("Abercrombie", instructor.LastName);
        }

        [Fact]
        public void Initialize_CreatesOfficeAssignments()
        {
            var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var fakhouri = context.Instructors.First(i => i.LastName == "Fakhouri");
            var office = context.OfficeAssignments.Find(fakhouri.ID);
            Assert.NotNull(office);
            Assert.Equal("Smith 17", office.Location);
        }

        [Fact]
        public void Initialize_CreatesEnrollmentsWithGrades()
        {
            var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var enrollmentsWithGrades = context.Enrollments.Where(e => e.Grade != null).Count();
            var enrollmentsWithoutGrades = context.Enrollments.Where(e => e.Grade == null).Count();

            Assert.True(enrollmentsWithGrades > 0);
            Assert.True(enrollmentsWithoutGrades > 0);
        }
    }

    public class SchoolContextTests
    {
        [Fact]
        public void SchoolContext_HasAllDbSets()
        {
            var context = TestDbContextFactory.Create();

            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.People);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Notifications);

            context.Dispose();
        }

        [Fact]
        public void SchoolContext_CourseAssignment_HasCompositeKey()
        {
            var context = TestDbContextFactory.Create();

            var ca1 = new CourseAssignment { CourseID = 100, InstructorID = 200 };
            context.CourseAssignments.Add(ca1);
            context.SaveChanges();

            var found = context.CourseAssignments.Find(100, 200);
            Assert.NotNull(found);

            context.Dispose();
        }

        [Fact]
        public void SchoolContext_TPH_CanQueryStudentsAndInstructors()
        {
            var context = TestDbContextFactory.Create();

            context.Students.Add(new Student
            {
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.Now
            });
            context.Instructors.Add(new Instructor
            {
                LastName = "Test",
                FirstMidName = "Instructor",
                HireDate = DateTime.Now
            });
            context.SaveChanges();

            Assert.Single(context.Students);
            Assert.Single(context.Instructors);
            Assert.Equal(2, context.People.Count());

            context.Dispose();
        }
    }
}

