using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerFileUploadTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly string _tempDir;

        public CoursesControllerFileUploadTests()
        {
            _context = TestDbContextFactory.CreateWithData();
            _tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_tempDir);

            var envMock = new Mock<IWebHostEnvironment>();
            envMock.Setup(e => e.WebRootPath).Returns(_tempDir);
            envMock.Setup(e => e.ContentRootPath).Returns(_tempDir);
            var loggerMock = new Mock<ILogger<CoursesController>>();

            _controller = new CoursesController(_context, envMock.Object, loggerMock.Object);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new TestTempDataProvider());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            if (Directory.Exists(_tempDir))
                Directory.Delete(_tempDir, true);
        }

        [Fact]
        public void Create_Post_ValidImage_UploadsAndRedirects()
        {
            var course = new Course
            {
                CourseID = 3001,
                Title = "Art Course",
                Credits = 2,
                DepartmentID = 1
            };
            var fileMock = CreateMockFile("photo.png", 1024);

            var result = _controller.Create(course, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            var savedCourse = _context.Courses.Find(3001);
            Assert.NotNull(savedCourse.TeachingMaterialImagePath);
            Assert.Contains("/Uploads/TeachingMaterials/", savedCourse.TeachingMaterialImagePath);
        }

        [Fact]
        public void Edit_Post_ValidImage_UploadsAndRedirects()
        {
            var course = new Course
            {
                CourseID = 1001,
                Title = "Intro to CS",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = null
            };
            _context.Entry(_context.Courses.Find(1001)).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var fileMock = CreateMockFile("new_image.jpg", 2048);

            var result = _controller.Edit(course, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void Create_Post_AllowedExtensions_Accepted(string extension)
        {
            var course = new Course
            {
                CourseID = 4000 + extension.GetHashCode() % 1000,
                Title = "Test " + extension,
                Credits = 3,
                DepartmentID = 1
            };
            var fileMock = CreateMockFile($"image{extension}", 1024);

            var result = _controller.Create(course, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void DeleteConfirmed_CourseWithImage_DeletesImageFile()
        {
            // Create a file to be "deleted"
            var uploadsDir = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(uploadsDir);
            var imagePath = Path.Combine(uploadsDir, "test_image.jpg");
            File.WriteAllText(imagePath, "fake image");

            var course = _context.Courses.Find(1001);
            course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/test_image.jpg";
            _context.SaveChanges();

            _controller.DeleteConfirmed(1001);

            Assert.False(File.Exists(imagePath));
        }

        private static Mock<IFormFile> CreateMockFile(string fileName, long size)
        {
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns(fileName);
            fileMock.Setup(f => f.Length).Returns(size);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));
            return fileMock;
        }
    }
}

